#!/usr/bin/env bash
# File cấu hình Nginx chuẩn Production (/etc/nginx/sites-available/app.conf)
cat << 'NGINX_CONF'
# Định nghĩa cụm upstream các backend servers (Load Balancing)
upstream nodejs_backend {
    server 127.0.0.1:3000 max_fails=3 fail_timeout=10s;
    server 127.0.0.1:3001 backup; # Instance dự phòng
    keepalive 32;                 # Giữ kết nối TCP ấm để giảm độ trễ
}

# 1. Virtual Host (Server Block) cho API Node.js
server {
    listen 80;
    server_name api.mycompany.com;

    location / {
        proxy_pass http://nodejs_backend;
        proxy_http_version 1.1;

        # Chuyển tiếp các header nhận diện client thực tế
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Hỗ trợ WebSockets nâng cấp kết nối
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";

        # Timeouts bảo vệ server
        proxy_connect_timeout 5s;
        proxy_read_timeout 60s;
    }
}
NGINX_CONF

