#!/usr/bin/env bash
# So sánh cấu hình L4 vs L7 trực tiếp trong Nginx

# 1. LAYER 4 LOAD BALANCING (Block 'stream' trong Nginx - TCP/UDP Passthrough)
# Không đọc nội dung gói tin, chỉ forward raw bytes dựa trên IP và Port
cat << 'EOF'
stream {
    upstream database_cluster {
        server 10.0.1.10:5432 weight=2;
        server 10.0.1.11:5432;
    }
    server {
        listen 5432; # Load balance cổng PostgreSQL
        proxy_pass database_cluster;
    }
}
EOF

# 2. LAYER 7 LOAD BALANCING (Block 'http' trong Nginx - Application Aware)
# Đọc và giải mã HTTP: Phân tích URI Path, Headers, Cookies để điều phối thông minh
cat << 'EOF'
http {
    upstream payment_service { server 10.0.2.10:8080; }
    upstream image_service   { server 10.0.2.20:8080; }
    server {
        listen 80;
        location /api/v1/payments { proxy_pass http://payment_service; }
        location /static/images   { proxy_pass http://image_service; }
    }
}
EOF

