// Minh họa Ba Trụ Cột của Observability (Three Pillars) trong cùng một request:

import { Request, Response } from 'express';
import { Counter, Histogram } from 'prom-client';
import pino from 'pino';
import { trace } from '@opentelemetry/api';

const logger = pino();
const httpDuration = new Histogram({ name: 'http_duration_seconds', help: 'Duration' });
const errorCounter = new Counter({ name: 'http_errors_total', help: 'Errors' });

export async function handleCheckout(req: Request, res: Response) {
  // 1. TRACE: Theo dõi ngữ cảnh luồng đi xuyên qua các microservices (Distributed Context)
  const currentSpan = trace.getActiveSpan();
  const traceId = currentSpan?.spanContext().traceId;

  const timer = httpDuration.startTimer();
  try {
    // 2. LOG: Dữ liệu chi tiết có cấu trúc gắn chặt với Trace ID
    logger.info({ traceId, userId: req.body.userId }, 'Bắt đầu xử lý thanh toán đơn hàng');

    await processPayment(req.body);
    res.json({ success: true });
  } catch (error) {
    // 3. METRIC: Dữ liệu số học có thể tổng hợp nhanh (Aggregatable Numbers)
    errorCounter.inc({ route: '/checkout', status: '500' });
    logger.error({ traceId, err: error }, 'Thanh toán thất bại');
    res.status(500).send('Error');
  } finally {
    timer();
  }
}

import { trace, context } from '@opentelemetry/api';

const tracer = trace.getTracer('payment-service');

// 1. TRACE: Toàn bộ hành trình của một request (tập hợp của nhiều Spans có chung Trace ID)
// 2. SPAN: Một đơn vị công việc duy nhất được thực hiện bởi một service trong một khoảng thời gian
export async function executePaymentWorkflow(orderId: string) {
  // Tạo Span cha (Parent Span)
  return tracer.startActiveSpan('executePaymentWorkflow', async (parentSpan) => {
    parentSpan.setAttribute('order.id', orderId);

    try {
      // Tạo Span con 1: Gọi sang Fraud Detection Service
      await tracer.startActiveSpan('checkFraudStatus', async (span1) => {
        // HTTP Header 'traceparent: 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01'
        // Context được tự động inject vào outgoing HTTP request để truyền qua service tiếp theo
        await callFraudApi(orderId);
        span1.end(); // Kết thúc đo thời gian của Span 1
      });

      // Tạo Span con 2: Ghi vào CSDL
      await tracer.startActiveSpan('databaseDeductFunds', async (span2) => {
        await db.wallet.update({ where: { orderId }, data: { status: 'PAID' } });
        span2.end();
      });
    } finally {
      parentSpan.end(); // Kết thúc toàn bộ Trace
    }
  });
}

// Minh họa toán học về SLI, SLO và Error Budget trong hệ thống thanh toán:

// 1. SLI (Service Level Indicator): Chỉ số đo lường thực tế
// Tỷ lệ phần trăm các request thành công có độ trễ < 500ms
const totalRequests = 10_000_000;
const successfulRequests = 9_995_000;
const currentSLI = (successfulRequests / totalRequests) * 100; // = 99.95%

// 2. SLO (Service Level Objective): Mục tiêu nội bộ mà team SRE cam kết
const targetSLO = 99.9; // 99.9% Uptime trong chu kỳ 30 ngày rolling window

// 3. SLA (Service Level Agreement): Cam kết pháp lý với khách hàng (Kèm bồi thường tiền tệ)
const contractSLA = 99.0; // Nếu tụt dưới 99.0%, công ty phải đền tiền cho khách hàng!
// Quy tắc vàng: SLA luôn lỏng hơn SLO (SLO > SLA) để tạo vùng đệm an toàn!

// 4. ERROR BUDGET (Ngân sách lỗi cho phép trong 30 ngày):
// Ngân sách lỗi = 100% - 99.9% = 0.1% tổng số request = 10,000 requests được phép lỗi!
const failedRequests = totalRequests - successfulRequests; // = 5,000
const remainingErrorBudget = 10_000 - failedRequests; // Còn lại 5,000 requests (50%)
// NẾU HẾT ERROR BUDGET (0%): LẬP TỨC ĐÓNG BĂNG RELEASE TÍNH NĂNG MỚI, CHỈ TẬP TRUNG FIX BUG!
